Decorators with arguments.code:
from functools import wraps
def retry(max_attempts=3):
    def decorator(fn):
        @wraps(fn)
        def wrapper(*a, **kw):
            for i in range(max_attempts):
                try: return fn(*a, **kw)
                except: pass
        return wrapper
    return decorator

