Observer events pub-sub.code:
class EventEmitter:
    def __init__(self): self._handlers = {}
    def on(self, event, fn): self._handlers.setdefault(event, []).append(fn)
    def emit(self, event, *a, **kw):
        for h in self._handlers.get(event, []): h(*a, **kw)

